(() => {'use strict';const $=id=>document.getElementById(id),g=()=>window.gameDebug;
function close(){const d=$('modal');d.close();}
function button(label,fn){const b=document.createElement('button');b.textContent=label;b.onclick=()=>{close();fn();};b.className='menu-option';return b;}
function actions(){const d=$('actions-panel');$('combat-tools').hidden=false;d.showModal();}
function menu(){const d=$('modal'),body=$('modal-body');$('modal-title').textContent='Меню';body.replaceChildren(button('Сохранить и выйти в меню героев',()=>window.Worlds.exitToMenu()),button('Текущий мир',()=>window.Worlds.open()),button('Мои герои',()=>window.Heroes.open()),button('Эпизод · Пропавший послушник',()=>window.Episode.open()),button('Действия героя',actions),button('Кубики',()=>$('dice-panel').showModal()),button('Хроника',()=>g().journal()),button('Как играть',()=>g().help()),button('Правила и источники',()=>{const d=$('modal');$('modal-title').textContent='Правила и источники';const p=document.createElement('p');p.textContent='Основа: SRD 5.2.1 · CC BY 4.0.';const a=document.createElement('a');a.href='rules.html';a.textContent='Открыть правила, источники и домашние изменения';$('modal-body').replaceChildren(p,a);d.showModal();}),button('Мастерская · проверки и настройки',()=>window.Worlds.workshop()));d.showModal();}
function init(){const tools=$('combat-tools'),d=document.createElement('dialog');d.id='actions-panel';const head=document.createElement('div');head.className='modal-head';const title=document.createElement('h2');title.textContent='Действия героя';const b=document.createElement('button');b.append(UIIcons.node('close'));b.setAttribute('aria-label','Закрыть действия');b.onclick=()=>d.close();head.append(title,b);d.append(head,tools);document.body.append(d);const toggle=$('combat-tools-toggle');toggle.innerHTML='<span>···</span><b>Действия</b>';toggle.onclick=actions;$('end').before(toggle);$('menu').onclick=menu;$('tab-test').hidden=true;$('menu').textContent='☰';$('menu').setAttribute('aria-label','Меню');$('menu').setAttribute('aria-haspopup','dialog');const ledger=$('roll-log').closest('details');ledger.removeAttribute('open');$('journal').after(ledger);$('camera-center').textContent='◎';$('camera-center').setAttribute('aria-label','Центрировать на герое');$('camera-fit').textContent='⛶';$('camera-fit').setAttribute('aria-label','Показать всю карту');render();}
function render(){if(!g())return;const s=g().state;document.body.classList.toggle('in-combat',s.combat);$('end').hidden=!s.combat;$('turn-resources').parentElement.hidden=!s.combat;$('learning-tip').hidden=true;$('light-state').hidden=true;$('rules-credit')?.classList.add('workshop-only');}
window.GameMenu={init,render,open:menu,actions};})();
